const routes=['discover','search','saved','compare?ids=north,morrow','job/morrow','apply/north','applications','receipt/DEMO-preview-0001','profile'];const nav=document.querySelector('#review-nav');for(const route of routes){const a=document.createElement('a');a.className='btn';a.textContent=route.split('?')[0];a.href='#'+route;nav.append(a);}function show(){const route=location.hash.slice(1)||'discover';for(const frame of document.querySelectorAll('iframe'))frame.src='index.html?preview=1'+(/^(saved|compare)/.test(route)?'&case=shortlist':/^(applications|receipt)/.test(route)?'&case=recorded':'')+'#/'+route;}window.addEventListener('hashchange',show);show();

if(new URLSearchParams(location.search).has('capture')){document.body.classList.add('capture-board');document.querySelector('.device:first-child h2').textContent='Mobile · 390 × 640';document.querySelector('.device:nth-child(2) h2').textContent='Desktop · 1440 × 640';}
